-- Tabella di riferimento comuni italiani (ISTAT), per popolare in automatico
-- provincia/comune -> CAP + codice catastale nei form indirizzo (brief:
-- "codice_catastale_comune ... puo' essere auto-popolato da tabella comuni
-- ISTAT/catastale"). Sola lettura per gli utenti applicativi: nessuna UI di
-- modifica, si aggiorna solo con una nuova migration se ISTAT cambia
-- denominazioni/confini comunali.
-- Dataset sorgente: https://github.com/matteocontrini/comuni-json (ISTAT),
-- scaricato il 2026-09-10. cap_alternativi copre i (pochi, 44) comuni con piu'
-- di un CAP: il form propone il primo come default, editabile a mano.
create table comuni (
  codice_catastale text primary key,
  nome text not null,
  provincia_sigla text not null,
  provincia_nome text not null,
  cap text not null,
  cap_alternativi text[] not null default '{}'
);

create index idx_comuni_provincia_sigla on comuni (provincia_sigla);

grant select on comuni to authenticated;
alter table comuni enable row level security;
create policy "authenticated_read" on comuni for select to authenticated using (true);

